exercises.starter:
function getOrDefault(obj, key, fallback) {
  // return the stored value if the key exists, else fallback
}

exercises.solution:
function getOrDefault(obj, key, fallback) {
  return key in obj ? obj[key] : fallback
}

exercises.starter:
function sumValues(obj) {
  // add up every value in the object
}

exercises.solution:
function sumValues(obj) {
  return Object.values(obj).reduce((sum, x) => sum + x, 0)
}

exercises.starter:
function invert(obj) {
  // return a new object with keys and values swapped
}

exercises.solution:
function invert(obj) {
  const result = {}
  for (const [key, value] of Object.entries(obj)) {
    result[value] = key
  }
  return result
}

exercises.starter:
function keysWhere(obj, min) {
  // return the keys whose value is at least min
}

exercises.solution:
function keysWhere(obj, min) {
  return Object.keys(obj).filter(key => obj[key] >= min)
}

exercises.starter:
function pickDefined(obj, keys) {
  // copy over only the requested keys that exist on obj
}

exercises.solution:
function pickDefined(obj, keys) {
  const result = {}
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key]
    }
  }
  return result
}
